<header class="page-header"><div class="page-header-copy"><p class="eyebrow">Staff access</p><h1><?= $editing ? 'Edit staff account' : 'New staff account' ?></h1><p>Identity and access details for a GROOVE team member.</p></div></header>
<section class="panel form-panel"><form action="<?= $editing ? site_url('staff/' . $staffMember['id']) : site_url('staff') ?>" method="post" enctype="multipart/form-data" class="form-stack" novalidate>
<?= csrf_field() ?>
<div class="form-grid"><div class="field"><label for="full_name">Full name</label><input id="full_name" name="full_name" maxlength="100" autocomplete="name" value="<?= esc(old('full_name', $staffMember['full_name'] ?? '')) ?>" required <?= isset($errors['full_name']) ? 'aria-invalid="true" aria-describedby="staff-name-error"' : '' ?>><small class="field-error" id="staff-name-error"><?= esc($errors['full_name'] ?? '') ?></small></div><div class="field"><label for="username">Username</label><input id="username" name="username" maxlength="50" value="<?= esc(old('username', $staffMember['username'] ?? '')) ?>" autocomplete="off" required <?= isset($errors['username']) ? 'aria-invalid="true" aria-describedby="username-help username-error"' : 'aria-describedby="username-help"' ?>><small id="username-help">Letters, numbers, dots, underscores, and hyphens.</small><small class="field-error" id="username-error"><?= esc($errors['username'] ?? '') ?></small></div></div>
